from fastapi import FastAPI, Header
from fastapi.testclient import TestClient

app = FastAPI()

@app.get("/")
async def read_header(my_header: str = Header()):
    return {"my_header": my_header}

client = TestClient(app)

def test_underscore_header():
    # By default convert_underscores=True.
    # It should accept 'my-header'
    response = client.get("/", headers={"my-header": "foo"})
    assert response.json() == {"my_header": "foo"}

    # It should NOT accept 'my_header'
    response = client.get("/", headers={"my_header": "bar"})
    # If it's NOT accepted, it should probably be a 422 Unprocessable Entity
    # because my_header is a required header.
    assert response.status_code == 422

def test_underscore_header_disabled():
    # Now we disable convert_underscores
    @app.get("/disabled")
    async def read_header_disabled(my_header: str = Header(convert_underscores=False)):
        return {"my_header": my_header}

    # It should accept 'my_header'
    response = client.get("/disabled", headers={"my_header": "bar"})
    assert response.json() == {"my_header": "bar"}

if __name__ == "__main__":
    try:
        test_underscore_header()
        print("test_underscore_header passed")
    except Exception as e:
        print(f"test_underscore_header failed: {e}")

    try:
        test_underscore_header_disabled()
        print("test_underscore_header_disabled passed")
    except Exception as e:
        print(f"test_underscore_header_disabled failed: {e}")

